[900100] = {chapterid = 900100, chaptertype = 1, chapternum = "s1-1", chaptername = "倖存者X", chapterdesc = "你在陌生的房間中醒來，面對你的是不認識的少女們，她們告訴你這裡是一座孤島，而你是唯一的男性……所以，你接下來何去何從？", scrollid = 1, pickicon = "Activity/Summer/ChapterIcon/Img_Xuexiao_shang", chapterpicture = "Activity/Summer/BackGround/Img_Bg_Raid1", scrollpicture = "Activity/Summer/Map/MapBG1", bossbackground = "0", bosspicture = "0", bosspos = "0", levels = "9001000,9001001,9001002,9001003,9001004,9001005,9001006,9001007", unlocklevel = "9001300", plot = "0", chaptermusic = "33-Empty_but_not_real", scrollmusic = "33-Empty_but_not_real", chaptertime = 910001, awardview = "1_100000_0,1_100001_0,4_100000_0", objectivetips = "擊敗最終節點敵人", mapmode = 1, walkman = "1000012,summer"},
[900101] = {chapterid = 900101, chaptertype = 1, chapternum = "s1-2", chaptername = "齒輪向前", chapterdesc = "只有斯卡蒂能打開的門？被領航打開的門竟然連通著艾吉斯的秘密實驗室？在培養槽中的是——那位傳說中失蹤很久的偶像！", scrollid = 1, pickicon = "Activity/Summer/ChapterIcon/Img_Diaxiashi_shang", chapterpicture = "Activity/Summer/BackGround/Img_Bg_Raid1", scrollpicture = "Activity/Summer/Map/MapBG2", bossbackground = "0", bosspicture = "0", bosspos = "0", levels = "9001010,9001012,9001013,9001015,9001016,9001017,9001018,9001019,9001020,9001021", unlocklevel = "0", plot = "0", chaptermusic = "33-Empty_but_not_real", scrollmusic = "33-Empty_but_not_real", chaptertime = 910001, awardview = "1_100000_0,1_100001_0,4_100000_0", objectivetips = "尋找門後的聲音", mapmode = 2, walkman = "1000012,summer"},
[900102] = {chapterid = 900102, chaptertype = 1, chapternum = "s1-3", chaptername = "必殺技的意義！", chapterdesc = "能實現任何願望的泉水會給許願者懲罰嗎？想要拿取亞瑟王的聖劍還為時尚早！", scrollid = 1, pickicon = "Activity/Summer/ChapterIcon/Img_Senlin1_shang", chapterpicture = "Activity/Summer/BackGround/Img_Bg_Raid1", scrollpicture = "Activity/Summer/Map/MapBG1", bossbackground = "0", bosspicture = "0", bosspos = "0", levels = "9001030,9001031,9001032,9001033,9001035,9001036,9001037,9001038,9001039,9001040,9001041,9001042,9001043,9001044,9001045,9001046", unlocklevel = "9001301", plot = "0", chaptermusic = "33-Empty_but_not_real", scrollmusic = "33-Empty_but_not_real", chaptertime = 910001, awardview = "1_100000_0,1_100001_0,4_100000_0", objectivetips = "尋找斯卡蒂並與其對話", mapmode = 1, walkman = "1000012,summer"},
[900103] = {chapterid = 900103, chaptertype = 1, chapternum = "s1-4", chaptername = "各自的修煉", chapterdesc = "為了見到另一個斯卡蒂，領航決定快速清理島上的原罪。", scrollid = 1, pickicon = "Activity/Summer/ChapterIcon/Img_Senlin2_shang", chapterpicture = "Activity/Summer/BackGround/Img_Bg_Raid1", scrollpicture = "Activity/Summer/Map/MapBG1", bossbackground = "0", bosspicture = "0", bosspos = "0", levels = "9001050,9001051,9001052,9001053,9001054,9001055,9001056,9001057,9001058,9001059,9001060,9001061,9001062,9001063,9001064", unlocklevel = "0", plot = "0", chaptermusic = "33-Empty_but_not_real", scrollmusic = "33-Empty_but_not_real", chaptertime = 910001, awardview = "1_100000_0,1_100001_0,4_100000_0", objectivetips = "擊敗最終節點敵人", mapmode = 1, walkman = "1000012,summer"},
[900104] = {chapterid = 900104, chaptertype = 1, chapternum = "s1-5", chaptername = "鏡子的正面", chapterdesc = "面對預言師給出的速通路線，大家的選擇是什麼？另一座孤島在地圖上被標示了出來，但是阻撓著領航一行人的是昔日的夥伴——", scrollid = 1, pickicon = "Activity/Summer/ChapterIcon/Img_Yiji_shang", chapterpicture = "Activity/Summer/BackGround/Img_Bg_Raid1", scrollpicture = "Activity/Summer/Map/MapBG1", bossbackground = "0", bosspicture = "0", bosspos = "0", levels = "9001070,9001071,9001072,9001073,9001074,9001075,9001076,9001077,9001078,9001079,9001080,9001081,9001082,9001083,9001084,9001085,9001086,9001087,9001088", unlocklevel = "9001302", plot = "0", chaptermusic = "33-Empty_but_not_real", scrollmusic = "33-Empty_but_not_real", chaptertime = 910001, awardview = "1_100000_0,1_100001_0,4_100000_0", objectivetips = "擊敗最終節點敵人", mapmode = 1, walkman = "1000012,summer"},
[900140] = {chapterid = 900140, chaptertype = 2, chapternum = "s2-1", chaptername = "席茲的試煉", chapterdesc = "來自太古的舊王，從百萬年的長眠中醒來，退化成雛鳥遇上了執掌光與暗權能的女王的那個巨鳥席茲。", scrollid = 3, pickicon = "Activity/Summer/BackGround/Img_Boss1di", chapterpicture = "Activity/Summer/BackGround/Img_Bg_Boss1", scrollpicture = "0", bossbackground = "Activity/Summer/BackGround/Img_Boss1Tanchuangdi", bosspicture = "Activity/Summer/BackGround/Img_Boss1", bosspos = "22,242", levels = "9001400,9001401", unlocklevel = "0", plot = "0", chaptermusic = "31-battle_xizi", scrollmusic = "0", chaptertime = 910001, awardview = "0", objectivetips = "0", mapmode = 0, walkman = "0"},
